#![allow(unused)]
use verus::prelude::*;

/// Returns true precisely when the grid is “disconnected” at the corners,
/// i.e. one of the four forbidden corner‐patterns occurs.
#[requires(n as usize >= 1)]
#[requires(m as usize >= 1)]
#[requires(horizontal.len() == n as usize)]
#[requires(vertical.len()   == m as usize)]
#[ensures(
    result
    == (
        // top-left corner
        (horizontal[0]             == '>' && vertical[0]             == 'v')
        // top-right corner
     || (horizontal[0]             == '<' && vertical[m as usize-1] == 'v')
        // bottom-left corner
     || (horizontal[n as usize-1] == '>' && vertical[0]             == '^')
        // bottom-right corner
     || (horizontal[n as usize-1] == '<' && vertical[m as usize-1] == '^')
    )
)]
fn check_disconnected(
    n: i8,
    m: i8,
    horizontal: &Vec<char>,
    vertical:   &Vec<char>,
) -> bool {
    // Convert to usize for indexing
    let n = n as usize;
    let m = m as usize;

    // Read the four corner characters
    let first_h = horizontal[0];
    let last_h  = horizontal[n - 1];
    let first_v = vertical[0];
    let last_v  = vertical[m - 1];

    // Return true exactly when one of the four bad patterns holds
    (first_h == '>' && first_v == 'v')
        || (first_h == '<' && last_v  == 'v')
        || (last_h  == '>' && first_v == '^')
        || (last_h  == '<' && last_v  == '^')
}

/// Produces “NO\n” if the corners are disconnected,
/// otherwise “YES\n”.
#[requires(n as usize >= 1)]
#[requires(m as usize >= 1)]
#[requires(horizontal.len() == n as usize)]
#[requires(vertical.len()   == m as usize)]
#[ensures(
    if check_disconnected(n, m, &horizontal, &vertical) {
        result == vec!['N','O','\n']
    } else {
        result == vec!['Y','E','S','\n']
    }
)]
fn solve(
    n: i8,
    m: i8,
    horizontal: Vec<char>,
    vertical:   Vec<char>,
) -> Vec<char> {
    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N','O','\n']
    } else {
        vec!['Y','E','S','\n']
    }
}